/**
 * The rule for a password the owner chooses later (change, reset, recovery), and for a setup
 * password a deployment supplies (OWNER_SETUP_PASSWORD). The offline CLI carries the same rule in
 * scripts/recovery-core.mjs, and test/password-policy.spec.ts checks that the two agree. Length counts Unicode code
 * points, so an emoji is one character here and in the CLI. At least one letter and one digit are required; mixed case is not.
 * The first Owner password is generated by the Worker when the deployment supplies none, and is not checked by this rule.
 */
export const MIN_PASSWORD_LENGTH = 8;

export type PasswordProblem = 'TOO_SHORT' | 'NEEDS_LETTER_AND_DIGIT' | 'WEAK';

const LETTER = /\p{L}/u;
const DIGIT = /\p{Nd}/u;
const PLACEHOLDER = /replace[-_]?with|change[-_]?me/i;
const MIN_DISTINCT_CHARACTERS = 4;
// Short, well-known choices that a guesser tries first. Compared in lower case.
const COMMON = new Set([
	'password',
	'password1',
	'password123',
	'12345678',
	'123456789',
	'1234567890',
	'qwertyui',
	'qwerty123',
	'letmein1',
	'iloveyou',
	'abcdefgh',
	'abcd1234',
	'admin123',
]);

/** Returns why the password is not acceptable, or null when it is. Never includes the password itself. */
export function passwordProblem(password: string): PasswordProblem | null {
	if ([...password].length < MIN_PASSWORD_LENGTH) return 'TOO_SHORT';
	if (!LETTER.test(password) || !DIGIT.test(password)) return 'NEEDS_LETTER_AND_DIGIT';
	if (PLACEHOLDER.test(password) || new Set(password).size < MIN_DISTINCT_CHARACTERS || COMMON.has(password.toLowerCase())) {
		return 'WEAK';
	}
	return null;
}
